typedef void (*Callback)(const char *event);
void register_callback(Callback cb);
void trigger_event(const char *event);
Callback current_callback = NULL;
void register_callback(Callback cb) {
    current_callback = cb;
}
void trigger_event(const char *event) {
    if (current_callback) {
        current_callback(event);
    }
}
void handle_event(const char *event) {
    printf("Handling event: %s\n", event);
}
int main() {
    register_callback(handle_event);
    trigger_event("Panda to ZooAnimal reference");
    return 0;
}
